(function(root){
 'use strict';
 const K=AstraCareerCore;
 const e=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const section=t=>`<div class="section-title"><span>✧</span><h3>${t}</h3><span class="line"></span></div>`;
 const sourceLinks=`<a href="https://4uinstitute.com/cht/index.php?act=class&code=content&ids=22" target="_blank" rel="noopener noreferrer">4U 官方課程介紹 ↗</a><a href="https://www.everythingdisc.com/what-is-disc/" target="_blank" rel="noopener noreferrer">DISC 模型介紹 ↗</a>`;
 function result(state,m){
  if(!state.submitted)return `<div class="career-empty"><span>◎</span><h4>從實際行為，認識自己的工作節奏。</h4><p>完成下方 16 題，才會產生你的 D／I／S／C 風格摘要。生日不會參與這份自評的計分。</p></div>`;
  const r=K.score(state.answers),label=r.balanced?'多元均衡傾向':r.leaders.map(k=>`${k} ${K.styles[k].name}`).join(' ＋ ');
  return `<div class="career-result-head"><div class="eyebrow">YOUR BEHAVIORAL PREFERENCES</div><h3>${label}</h3><p>${r.balanced?'四項回答相近，宜結合具體情境理解，不強行指定單一類型。':r.leaders.length>1?'最高分並列，保留所有同分風格，不強行排序。':'這是你本次自述中較突出的方向，並不表示其他能力較弱。'}</p></div><div class="disc-scores">${Object.entries(K.styles).map(([key,s])=>`<div class="disc-score" style="--disc-color:${s.color}"><div><strong>${key}</strong><span>${s.name}</span><b>${r.averages[key].toFixed(2)} / 5</b></div><div class="disc-track"><span style="width:${r.averages[key]/5*100}%"></span></div><small>${s.focus}</small></div>`).join('')}</div><div class="note-box">每項為 4 題回答的平均值；不是能力排名、人口百分位或正式測驗常模。</div>${section('把風格轉成工作與溝通的選擇')}<div class="career-guides">${(r.balanced?Object.keys(K.styles):r.leaders).map(key=>{const s=K.styles[key];return `<article class="detail-card"><div class="kicker">${key} / ${s.en.toUpperCase()}</div><h3>${s.name}的實踐方向</h3><p><b>優勢：</b>${s.strength}</p><p><b>留意：</b>${s.blind}</p><p><b>工作情境：</b>${s.work}</p><p><b>溝通調整：</b>${s.communicate}</p><p class="career-action"><b>本週實驗：</b>${s.practice}事後記下一個有效之處與一個要調整的地方。</p></article>`;}).join('')}</div>${section('和生日原型一起對照')}<div class="insight-card"><span class="quote">“</span><div><h3>${e(m.s.name)} × 靈數 ${m.calc.number} × 行為觀察</h3><p>生日報告以「${e(m.s.tags[0])}」與「${e(m.n.tags[0])}」提供象徵性的提問；這次自評反映的是你描述的行為。想想：在哪個真實情境中，它們相近？又在哪個情境中不相同？以經驗修正描述，不用一套結果證明另一套。</p></div></div>`;
 }
 function fourUSummary(f){return f?`<article class="detail-card fouru-summary"><div class="kicker">4U / USER-IMPORTED EXCERPT</div><h3>${e(f.role||'你匯入的 4U 報告摘錄')}</h3><p class="career-source">來源：${e(f.source)}${f.code?' · 代碼：'+e(f.code):''}</p>${[['strengths','優勢'],['blindspots','盲點'],['guidance','建議'],['rawText','報告原文']].filter(([k])=>f[k]).map(([k,t])=>`<div class="imported-text"><b>${t}</b><p>${e(f[k])}</p></div>`).join('')}<p class="note-box">使用者提供的內容，ASTRA 未核驗其來源或正確性；未由生日重新計算 4U 結果。</p></article>`:'<p class="note-box">尚未匯入 4U 結果。沒有正式報告，也可以先完成獨立的行為自評。</p>';}
 function render(state,m,current){
  const f=state.fourU||{},count=Object.keys(state.answers).length;
  const intro=`<div class="career-banner"><div><div class="eyebrow">CAREER & BEHAVIOR · A NEW LENS</div><h3>4U 生涯運數 × DISC 行為探索</h3><p>把正式報告帶進來，再用實際行為與工作經驗，練習更適合自己的回應。</p></div><span class="career-orbit" aria-hidden="true">◎</span></div><div class="career-context"><span>☉ 星座與靈數：生日象徵</span><span>▱ 4U：你提供的正式結果</span><span>◈ DISC：獨立行為自評</span></div><p class="career-disclosure">4U 是 4U 人際教育學院的特定體系。本功能匯入既有報告，不重建其非公開公式。下方題目為 ASTRA 自編的 DISC 概念練習，未經標準化驗證，非 4U 或 Everything DiSC 官方測驗，也不代表雙方合作或認證。</p>`;
  if(current.example)return intro+`<div class="career-empty"><span>✧</span><h4>先建立你的生日檔案</h4><p>輸入生日並產生報告後，就能匯入 4U 結果、完成行為自評，並一併收藏與下載。</p><button type="button" class="primary-button" id="career-start">輸入我的生日 ↗</button></div><div class="career-links">${sourceLinks}</div>`;
  return intro+`<div class="career-toolbar"><span>目前檔案：${e(current.name||'我的星序')} · ${e(current.date)}</span><button type="button" class="secondary-button" id="career-export">下載生涯檔案 .json ↓</button></div>${section('01 · 匯入你的 4U 正式結果')}${fourUSummary(state.fourU)}<details id="fouru-editor" ${state.fourU?'':'open'}><summary>${state.fourU?'修改或重新匯入 4U 摘錄':'貼上報告文字，或讀取 .txt / ASTRA .json'}</summary><div><form id="fouru-form" novalidate><div class="fouru-fields"><label>報告來源／名稱<input name="source" maxlength="100" value="${e(f.source||'')}" placeholder="例如：個人諮詢報告／提供者名稱"></label><label>報告中的人格／角色名稱<input name="role" maxlength="100" value="${e(f.role||'')}" placeholder="照正式報告填寫，選填"></label><label>報告代碼<input name="code" maxlength="80" value="${e(f.code||'')}" placeholder="照原報告填寫，選填"></label></div>${[['strengths','優勢摘要',1500],['blindspots','盲點摘要',1500],['guidance','成長建議',1500],['rawText','正式報告原文／補充文字',12000]].map(([key,label,max])=>`<label class="career-text-label">${label}<textarea name="${key}" maxlength="${max}" rows="${key==='rawText'?5:2}" placeholder="可貼上你已有報告中的文字">${e(f[key]||'')}</textarea></label>`).join('')}<div class="career-form-actions"><button class="primary-button" type="submit">匯入這份 4U 摘錄 ↗</button><label class="career-file-label">讀取 .txt / ASTRA .json<input id="career-file" type="file" accept=".txt,.json,text/plain,application/json"></label>${state.fourU?'<button class="secondary-button" type="button" id="fouru-remove">移除此摘錄</button>':''}</div><p class="form-error" role="alert" id="fouru-error"></p><p class="note-box">只在本機處理文字；PDF 請先複製文字。JSON 僅接受由 ASTRA 匯出的生涯檔案，生日須與目前檔案一致。</p></form></div></details>${section('02 · 你的 DISC 風格自評')}<div id="career-results">${result(state,m)}</div><details class="disc-questionnaire" id="disc-editor" ${state.submitted?'':'open'}><summary>${state.submitted?'查看或調整本次作答':'完成 16 題，產生行為風格報告'}</summary><div><p>請依最近三個月在日常或工作中的實際表現作答。每題皆為必答：1 很少、2 偶爾、3 有時、4 經常、5 幾乎總是。</p><form id="disc-form" novalidate>${K.questions.map((q,i)=>`<fieldset class="disc-question"><legend><span>${String(i+1).padStart(2,'0')}</span> ${q.text}</legend><div class="disc-options">${[1,2,3,4,5].map(v=>`<label><input type="radio" name="${q.id}" value="${v}" ${state.answers[q.id]===v?'checked':''}><span>${v}<small>${['','很少','偶爾','有時','經常','幾乎總是'][v]}</small></span></label>`).join('')}</div></fieldset>`).join('')}<div class="career-form-actions"><span id="disc-progress" aria-live="polite">${count} / 16 題已完成</span><button class="primary-button" type="submit">產生行為風格報告 ↗</button></div><p class="form-error" role="alert" id="disc-error"></p></form></div></details>${section('03 · 生涯行動紀錄')}<article class="detail-card"><h3>用一週驗證一個新回應</h3><p>選一個重要情境（會議、合作或人際互動）→ 記下當時的需求 → 試一次上方建議 → 記錄對方的回應及實際結果。保留有效的方法，再調整不適合的部分。</p><p style="margin-top:12px">${state.fourU?'對照你匯入的 4U 摘錄，挑選一項你也曾在生活中觀察到的特質。':'日後有正式 4U 報告時，可回到這裡匯入。'}角色描述與工作情境是探索方向，不是固定職業結論。</p></article><details><summary>資料來源、計分與保存方式</summary><div>DISC 四類概念為 D 推進、I 連結、S 支持、C 審慎；每類 4 題，各題 1–5 分。分項平均＝該類總分 ÷ 4。同分保留並列；四類總分最高與最低差距不超過 2 時，顯示多元均衡傾向。沒有常模、診斷或精準度主張。<br>作答和 4U 摘錄只留在本次頁面；點上方「收藏／更新收藏」才存至本瀏覽器，下載檔案由你保管。換生日會開啟新檔案。<div class="career-links">${sourceLinks}</div></div></details>`;
 }
 function bind(state,m,current,refresh,notify,focusBirthday){
  const $=s=>document.querySelector(s);
  if($('#career-start')){$('#career-start').onclick=focusBirthday;return;}
  $('#fouru-form').onsubmit=ev=>{ev.preventDefault();const data=Object.fromEntries(new FormData(ev.target));try{const f=K.cleanFourU(data,true);if(!f)throw new Error('請至少填入角色、代碼、摘要或報告原文其中一項。');state.fourU=f;refresh();notify('已匯入 4U 摘錄；可收藏或下載保留。');}catch(err){$('#fouru-error').textContent=err.message;}};
  if($('#fouru-remove'))$('#fouru-remove').onclick=()=>{state.fourU=null;refresh();notify('已移除本次頁面的摘錄；已存收藏需再按更新。');};
  $('#disc-form').addEventListener('change',ev=>{const id=ev.target.name;if(!K.questions.some(q=>q.id===id))return;state.answers[id]=Number(ev.target.value);if(state.submitted){state.submitted=false;$('#career-results').innerHTML='<p class="note-box">答案已變更，請重新產生報告。</p>';}$('#disc-progress').textContent=`${Object.keys(state.answers).length} / 16 題已完成`;$('#disc-error').textContent='';refresh(false);});
  $('#disc-form').onsubmit=ev=>{ev.preventDefault();try{K.score(state.answers);state.submitted=true;refresh();$('#career-results').scrollIntoView({behavior:'smooth',block:'start'});notify('行為自評已完成，結果來自本次作答。');}catch(err){$('#disc-error').textContent=err.message;const q=K.questions.find(q=>!state.answers[q.id]);if(q)document.querySelector(`input[name="${q.id}"]`).focus();}};
  $('#career-export').onclick=()=>{const payload={format:'astra-career-v1',birthday:current.date,career:K.normalize(state)};download(JSON.stringify(payload,null,2),`ASTRA-career-${current.date}.json`,'application/json');notify('已下載生涯檔案，可於同生日報告重新匯入。');};
  $('#career-file').onchange=async ev=>{const file=ev.target.files[0];if(!file)return;try{if(file.size>150000)throw new Error('請選擇小於 150 KB 的文字或 JSON 檔案。');const text=(await file.text()).replace(/^\uFEFF/,'');if(/\.json$/i.test(file.name)){const imported=K.parseImport(text,current.date);Object.assign(state,imported);}else if(/\.txt$/i.test(file.name)){state.fourU=K.cleanFourU({source:file.name,rawText:text},true);if(!state.fourU)throw new Error('文字檔沒有可匯入的內容。');}else throw new Error('支援 .txt 與 ASTRA 匯出的 .json，請勿直接選取 PDF。');refresh();notify('生涯資料已匯入；可收藏或下載保留。');}catch(err){$('#fouru-error').textContent=err.message;ev.target.value='';}};
 }
 function download(text,name,type){const url=URL.createObjectURL(new Blob(['\uFEFF'+text],{type:type+';charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 function text(state,m){let out='\n\n## 10 4U 報告匯入與 DISC 行為自評\n4U 結果由使用者提供，未核驗來源、未由生日重算。DISC 題目由 ASTRA 自編，非 4U 或 Everything DiSC 官方測驗，未經標準化驗證。\n';if(state.fourU){for(const [key,label] of [['source','來源'],['role','角色'],['code','代碼'],['strengths','優勢'],['blindspots','盲點'],['guidance','建議'],['rawText','原文']])if(state.fourU[key])out+=`\n${label}：${state.fourU[key]}\n`;}else out+='\n尚未匯入 4U 正式結果。\n';if(state.submitted){const r=K.score(state.answers);out+='\nDISC 分項平均（每類 4 題，每題 1–5 分，非百分位）：\n';for(const [key,s] of Object.entries(K.styles))out+=`${key} ${s.name}：${r.averages[key].toFixed(2)} / 5\n`;out+=r.balanced?'\n四項相近，顯示多元均衡傾向。\n':'\n最高分風格：'+r.leaders.join(' / ')+'。同分保留並列。\n';for(const key of (r.balanced?Object.keys(K.styles):r.leaders)){const s=K.styles[key];out+=`\n${key} ${s.name}\n優勢：${s.strength}\n盲點：${s.blind}\n工作情境：${s.work}\n溝通：${s.communicate}\n本週實驗：${s.practice}\n`;}out+=`\n對照提問：生日原型中的「${m.s.tags[0]}」與「${m.n.tags[0]}」，在你的真實行為中有哪些相近和不同？生日不參與 DISC 計分。\n`;}else out+='\n尚未完成 DISC 自評，不推定個人風格。\n';out+='\n來源：4U 人際教育學院 https://4uinstitute.com/cht/index.php?act=class&code=content&ids=22\nDISC 概念 https://www.everythingdisc.com/what-is-disc/\n';return out;}
 root.AstraCareerUI={render,bind,text};
})(globalThis);
